/** Measurement → exercise link: weaker regions with their numbers and the plan items they put on the plan. */
import type { AnalysisResult } from '../../core';
import { REGION_LABEL } from '../../rehab/exercises';
import { findings, synkFindings } from '../../rehab/findings';
import type { Plan } from '../../rehab/planner';
import { Icon } from '../icons';

export function FindingsToExercises({ analysis, plan, limit = 3 }: { analysis: AnalysisResult; plan: Plan; limit?: number }) {
  // In the synkinesis programme the reason to stretch is the co-movement, not weakness.
  const list =
    plan.phase === 'synkinesis'
      ? synkFindings(analysis)
          .slice(0, limit)
          .map((f) => ({ region: f.region, pct: null as number | null, evidence: f.evidence }))
      : findings(analysis)
          .slice(0, limit)
          .map((f) => ({ region: f.region, pct: f.pct as number | null, evidence: f.evidence }));
  if (!list.length && plan.phase === 'synkinesis')
    return <p class="small ink2">측정된 동반운동이 없습니다. 이완·스트레칭 위주로 유지하세요.</p>;
  if (!list.length) return <p class="small ink2">모든 부위가 건강한 쪽의 90% 이상 움직입니다. 유지 운동을 권장합니다.</p>;
  return (
    <div class="list">
      {list.map((f) => {
        const items = plan.items.filter((i) => i.region === f.region);
        return (
          <div class="finding">
            <div class="row between">
              <b>{plan.phase === 'synkinesis' ? `${REGION_LABEL[f.region]} (함께 움직이는 곳)` : REGION_LABEL[f.region]}</b>
              {f.pct === null ? (
                <span class="chip warn">동반운동</span>
              ) : (
                <span class={`chip ${f.pct < 50 ? 'warn' : ''} tabular`}>{f.pct}%</span>
              )}
            </div>
            <div class="xsmall ink2">{f.evidence}</div>
            {items.length > 0 ? (
              <div class="row wrap" style={{ gap: '6px', marginTop: '4px' }}>
                {items.map((i) => (
                  <a class="btn sm" href={`#/exercise/${i.exercise.id}`}>
                    {i.exercise.title} <Icon name="chev" />
                  </a>
                ))}
              </div>
            ) : (
              <div class="xsmall muted">
                {plan.phase === 'acute'
                  ? '급성기에는 이 부위도 부드러운 마사지로만 관리합니다.'
                  : '오늘 계획의 다른 운동으로 함께 관리합니다.'}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}
