/** Screen theme: light by default (warm, calm), dark or following the system on request. Per-device preference. */
export type ThemePref = 'light' | 'dark' | 'system';
const KEY = 'fsr.theme.v1';

export function getTheme(): ThemePref {
  try {
    const v = localStorage.getItem(KEY);
    return v === 'dark' || v === 'system' ? v : 'light';
  } catch {
    return 'light';
  }
}

export function applyTheme(pref: ThemePref = getTheme()): void {
  const root = document.documentElement;
  if (pref === 'system') delete root.dataset.theme;
  else root.dataset.theme = pref;
}

export function setTheme(pref: ThemePref): void {
  try {
    localStorage.setItem(KEY, pref);
  } catch {
    /* private mode: applies for this visit only */
  }
  applyTheme(pref);
}

/** Text size (per device): scales every font size through the --fs CSS variable. */
export type TextSize = 'normal' | 'large' | 'xlarge';
const TEXT_KEY = 'fsr.text.v1';

export function getTextSize(): TextSize {
  try {
    const v = localStorage.getItem(TEXT_KEY);
    return v === 'large' || v === 'xlarge' ? v : 'normal';
  } catch {
    return 'normal';
  }
}

export function applyTextSize(size: TextSize = getTextSize()): void {
  const root = document.documentElement;
  if (size === 'normal') delete root.dataset.text;
  else root.dataset.text = size;
}

export function setTextSize(size: TextSize): void {
  try {
    localStorage.setItem(TEXT_KEY, size);
  } catch {
    /* private mode: applies for this visit only */
  }
  applyTextSize(size);
}
