/**
 * Descriptive and agreement statistics used for robust aggregation and for
 * clinical-validation analyses (app vs clinician ratings).
 */

export function mean(xs: readonly number[]): number {
  if (xs.length === 0) return NaN;
  let s = 0;
  for (const x of xs) s += x;
  return s / xs.length;
}

export function median(xs: readonly number[]): number {
  if (xs.length === 0) return NaN;
  const a = [...xs].sort((p, q) => p - q);
  const m = a.length >> 1;
  return a.length % 2 ? a[m]! : (a[m - 1]! + a[m]!) / 2;
}

/** Sample standard deviation (n − 1). */
export function sd(xs: readonly number[]): number {
  if (xs.length < 2) return NaN;
  const m = mean(xs);
  let s = 0;
  for (const x of xs) s += (x - m) ** 2;
  return Math.sqrt(s / (xs.length - 1));
}

export const clamp = (x: number, lo: number, hi: number): number => Math.min(hi, Math.max(lo, x));

interface AnovaParts {
  n: number;
  k: number;
  msr: number;
  msc: number;
  mse: number;
}

function twoWayAnova(data: readonly (readonly number[])[]): AnovaParts {
  const n = data.length;
  const k = data[0]?.length ?? 0;
  if (n < 2 || k < 2 || data.some((r) => r.length !== k)) throw new Error('ICC requires an n×k matrix with n≥2, k≥2');
  const grand = mean(data.flat());
  let ssr = 0;
  let ssc = 0;
  let sst = 0;
  for (const row of data) ssr += k * (mean(row) - grand) ** 2;
  for (let j = 0; j < k; j++) ssc += n * (mean(data.map((r) => r[j]!)) - grand) ** 2;
  for (const row of data) for (const x of row) sst += (x - grand) ** 2;
  const sse = sst - ssr - ssc;
  return { n, k, msr: ssr / (n - 1), msc: ssc / (k - 1), mse: sse / ((n - 1) * (k - 1)) };
}

/**
 * Intraclass correlation (Shrout & Fleiss 1979), single measures.
 * data[i][j] = rating of subject i by rater/method j.
 *  - 'A,1' = ICC(2,1): two-way random, absolute agreement (primary endpoint).
 *  - 'C,1' = ICC(3,1): two-way mixed, consistency.
 */
export function icc(data: readonly (readonly number[])[], form: 'A,1' | 'C,1' = 'A,1'): number {
  const { n, k, msr, msc, mse } = twoWayAnova(data);
  if (form === 'C,1') return (msr - mse) / (msr + (k - 1) * mse);
  return (msr - mse) / (msr + (k - 1) * mse + (k * (msc - mse)) / n);
}

/**
 * Cohen's weighted kappa for two raters on an ordinal scale of `categories`
 * ordered levels (values must be integers 0..categories−1).
 */
export function weightedKappa(
  a: readonly number[],
  b: readonly number[],
  categories: number,
  weighting: 'quadratic' | 'linear' | 'none' = 'quadratic',
): number {
  if (a.length !== b.length || a.length === 0) throw new Error('kappa requires paired, non-empty ratings');
  const K = categories;
  const obs = Array.from({ length: K }, () => new Array<number>(K).fill(0));
  for (let i = 0; i < a.length; i++) obs[a[i]!]![b[i]!]! += 1;
  const n = a.length;
  const rowM = obs.map((r) => r.reduce((s, x) => s + x, 0) / n);
  const colM = Array.from({ length: K }, (_, j) => obs.reduce((s, r) => s + r[j]!, 0) / n);
  const w = (i: number, j: number): number => {
    if (weighting === 'none') return i === j ? 0 : 1;
    const d = Math.abs(i - j) / (K - 1);
    return weighting === 'quadratic' ? d * d : d;
  };
  let po = 0;
  let pe = 0;
  for (let i = 0; i < K; i++)
    for (let j = 0; j < K; j++) {
      po += w(i, j) * (obs[i]![j]! / n);
      pe += w(i, j) * rowM[i]! * colM[j]!;
    }
  return pe === 0 ? 1 : 1 - po / pe;
}

export interface BlandAltman {
  n: number;
  bias: number;
  sd: number;
  lower: number;
  upper: number;
}

/** Bland–Altman agreement: differences a − b with 95 % limits of agreement. */
export function blandAltman(a: readonly number[], b: readonly number[]): BlandAltman {
  const d = a.map((x, i) => x - b[i]!);
  const bias = mean(d);
  const s = sd(d);
  return { n: d.length, bias, sd: s, lower: bias - 1.96 * s, upper: bias + 1.96 * s };
}
