/**
 * Small responsive line chart (single y axis) with crosshair tooltip and
 * keyboard navigation. Follows the dataviz reference specs: 2px lines, ≥8px
 * markers with a 2px surface ring, hairline solid grid, text in ink tokens.
 */
import { useMemo, useRef, useState } from 'preact/hooks';

export interface Series {
  id: string;
  label: string;
  color: string;
  points: { x: number; y: number }[];
}

interface Props {
  series: Series[];
  yMax: number;
  yTicks: number[];
  ySuffix?: string;
  xLabel: (x: number) => string;
  xTitle: string;
  height?: number;
  ariaLabel: string;
  /** Extra tooltip lines per x (e.g. estimated HB grade). */
  extra?: (x: number) => string | null;
}

const W = 340;
const M = { l: 34, r: 14, t: 12, b: 34 };

function niceXTicks(min: number, max: number): number[] {
  const span = Math.max(1, max - min);
  const raw = span / 4;
  const pow = 10 ** Math.floor(Math.log10(raw));
  const step = [1, 2, 5, 10].map((m) => m * pow).find((s) => s >= raw) ?? raw;
  const out: number[] = [];
  for (let v = Math.ceil(min / step) * step; v <= max; v += step) out.push(v);
  return out;
}

export function LineChart({ series, yMax, yTicks, ySuffix = '', xLabel, xTitle, height = 210, ariaLabel, extra }: Props) {
  const ref = useRef<SVGSVGElement>(null);
  const [hover, setHover] = useState<number | null>(null);
  const H = height;
  const xs = useMemo(() => [...new Set(series.flatMap((s) => s.points.map((p) => p.x)))].sort((a, b) => a - b), [series]);
  const xMin = Math.min(0, xs[0] ?? 0);
  const xMax = Math.max(xMin + 7, xs[xs.length - 1] ?? 7);
  const sx = (x: number) => M.l + ((x - xMin) / (xMax - xMin)) * (W - M.l - M.r);
  const sy = (y: number) => M.t + (1 - y / yMax) * (H - M.t - M.b);
  const xTicks = niceXTicks(xMin, xMax);

  const pick = (clientX: number) => {
    const svg = ref.current;
    if (!svg || xs.length === 0) return;
    const r = svg.getBoundingClientRect();
    const vx = ((clientX - r.left) / r.width) * W;
    let best = 0;
    xs.forEach((x, i) => {
      if (Math.abs(sx(x) - vx) < Math.abs(sx(xs[best]!) - vx)) best = i;
    });
    setHover(best);
  };

  const hx = hover !== null ? xs[hover] : undefined;
  const tipLeftPct = hx !== undefined ? (sx(hx) / W) * 100 : 0;

  return (
    <div class="chart">
      <svg
        ref={ref}
        viewBox={`0 0 ${W} ${H}`}
        role="img"
        aria-label={ariaLabel}
        tabIndex={0}
        onPointerMove={(e) => pick(e.clientX)}
        onPointerDown={(e) => pick(e.clientX)}
        onPointerLeave={() => setHover(null)}
        onBlur={() => setHover(null)}
        onKeyDown={(e) => {
          if (xs.length === 0) return;
          if (e.key === 'ArrowRight') setHover((h) => Math.min(xs.length - 1, (h ?? -1) + 1));
          else if (e.key === 'ArrowLeft') setHover((h) => Math.max(0, (h ?? xs.length) - 1));
          else return;
          e.preventDefault();
        }}
      >
        {yTicks.map((t) => (
          <g>
            <line x1={M.l} x2={W - M.r} y1={sy(t)} y2={sy(t)} stroke={t === 0 ? 'var(--axis)' : 'var(--grid)'} stroke-width="1" />
            <text x={M.l - 6} y={sy(t) + 4} text-anchor="end" font-size="11" fill="var(--muted)" class="tabular">
              {t}
              {ySuffix}
            </text>
          </g>
        ))}
        {xTicks.map((t) => (
          <text x={sx(t)} y={H - M.b + 16} text-anchor="middle" font-size="11" fill="var(--muted)" class="tabular">
            {xLabel(t)}
          </text>
        ))}
        <text x={(M.l + W - M.r) / 2} y={H - 4} text-anchor="middle" font-size="11" fill="var(--muted)">
          {xTitle}
        </text>
        {hx !== undefined && <line x1={sx(hx)} x2={sx(hx)} y1={M.t} y2={H - M.b} stroke="var(--axis)" stroke-width="1" />}
        {series.map((s) => (
          <g>
            <polyline
              points={s.points.map((p) => `${sx(p.x)},${sy(p.y)}`).join(' ')}
              fill="none"
              stroke={s.color}
              stroke-width="2"
              stroke-linejoin="round"
              stroke-linecap="round"
            />
            {s.points.map((p) => (
              <circle cx={sx(p.x)} cy={sy(p.y)} r={p.x === hx ? 5.5 : 4} fill={s.color} stroke="var(--surface)" stroke-width="2" />
            ))}
          </g>
        ))}
      </svg>
      {hx !== undefined && (
        <div
          class="tip"
          style={{
            top: '4px',
            left: tipLeftPct > 55 ? undefined : `calc(${tipLeftPct}% + 10px)`,
            right: tipLeftPct > 55 ? `calc(${100 - tipLeftPct}% + 10px)` : undefined,
          }}
        >
          <div class="t">{xLabel(hx)}</div>
          {series.map((s) => {
            const p = s.points.find((q) => q.x === hx);
            return p ? (
              <div class="r">
                <span class="k" style={{ background: s.color }} />
                <b>
                  {Math.round(p.y)}
                  {ySuffix}
                </b>
                <span class="muted">{s.label}</span>
              </div>
            ) : null;
          })}
          {extra?.(hx) && <div class="r muted">{extra(hx)}</div>}
        </div>
      )}
    </div>
  );
}

export function Legend({ series }: { series: Series[] }) {
  if (series.length < 2) return null;
  return (
    <div class="legend">
      {series.map((s) => (
        <span>
          <i style={{ background: s.color }} />
          {s.label}
        </span>
      ))}
    </div>
  );
}
